import { evaluateApostilleRelationship, isApostilleConventionInForce, resolvePlace } from "@/lib/treaty/apostilleRelationship";

// Documents issued by supranational or intergovernmental organisations.
//
// Source: HCCH, Report of the Working Group on the Authentication of Documents Generated by
// Supranational and Intergovernmental Organisations, 1 December 2017, Conclusions &
// Recommendations No 3. The report RECOMMENDS three options a host State may use; it does not
// authorize any of them for a given organisation, authority or document. Each is therefore a
// candidate pathway that stays under review until the relevant authority's acceptance is
// evidenced and an operator approves it. An organisation's name is never evidence of authority,
// and nothing here issues, or claims to issue, an authentication.

export const INSTITUTIONAL_DOCUMENT_ORIGIN = "SUPRANATIONAL_OR_INTERGOVERNMENTAL_ORGANISATION" as const;

export const INSTITUTIONAL_SOURCE = {
  title: "HCCH Working Group Report on the Authentication of Documents Generated by Supranational and Intergovernmental Organisations",
  date: "2017-12-01",
  section: "Conclusions & Recommendations No 3",
  status: "recommendation",
} as const;

export const INSTITUTIONAL_PATHWAYS = {
  DIRECT_COMPETENT_AUTHORITY: "The host State's Competent Authority, holding the required sample signatures and seals of the organisation's officials, apostillises the document directly.",
  HOST_STATE_NOTARIAL_AUTHENTICATION: "A notary of the host State first authenticates the document or a copy; the host State's Competent Authority then apostillises that notarial authentication.",
  DESIGNATED_GOVERNMENT_INTERMEDIARY: "A government office designated by the host State, holding the required sample signatures and seals, authenticates the document; the Competent Authority then apostillises that authentication.",
} as const;
export type InstitutionalPathway = keyof typeof INSTITUTIONAL_PATHWAYS;

export type InstitutionalDecision = "VERIFIED_ROUTE" | "CONDITIONAL_REVIEW" | "UNSUPPORTED" | "UNKNOWN";

export type EvidenceItem = {
  state: "verified" | "unverified" | "rejected";
  source?: string | null; // official reference: URL or document identifier
  verifiedAt?: string | null; // ISO date
};

// What must be evidenced before a candidate pathway can be treated as a route.
export const INSTITUTIONAL_EVIDENCE = {
  issuerIdentity: "The issuing organisation is identified from the document itself and an official source.",
  issuerOfficialCapacity: "The signing official's capacity within the organisation is confirmed.",
  documentEligibility: "The document (or the copy to be authenticated) is of a kind the pathway's authority will act on.",
  competentAuthority: "The host State's Competent Authority has confirmed it will apostillise under this pathway.",
  signatureSealSpecimen: "The authority acting on the document holds, or has confirmed it can verify, the official's signature and seal.",
  hostStateNotary: "A notary of the host State is able and authorized to authenticate this document or copy.",
  designatedIntermediary: "The host State has designated the government office that will authenticate the document.",
  receivingAuthority: "The receiving authority's requirements for this document have been confirmed.",
} as const;
export type InstitutionalEvidenceKey = keyof typeof INSTITUTIONAL_EVIDENCE;

const COMMON: InstitutionalEvidenceKey[] = ["issuerIdentity", "issuerOfficialCapacity", "documentEligibility", "competentAuthority", "receivingAuthority"];
export const INSTITUTIONAL_PATHWAY_EVIDENCE: Record<InstitutionalPathway, InstitutionalEvidenceKey[]> = {
  DIRECT_COMPETENT_AUTHORITY: [...COMMON, "signatureSealSpecimen"],
  HOST_STATE_NOTARIAL_AUTHENTICATION: [...COMMON, "hostStateNotary"],
  DESIGNATED_GOVERNMENT_INTERMEDIARY: [...COMMON, "designatedIntermediary", "signatureSealSpecimen"],
};

// Evidence older than this must be re-verified before it supports a route.
export const INSTITUTIONAL_EVIDENCE_MAX_AGE_DAYS = 365;

export type InstitutionalRouteInput = {
  documentOrigin: string | null | undefined;
  issuingOrganisation?: string | null;
  hostState?: string | null; // country where the organisation issued the document
  destination?: string | null;
  documentCategory?: string | null;
  documentForm?: "original" | "certified_copy" | null;
  pathway?: InstitutionalPathway | null;
  evidence?: Partial<Record<InstitutionalEvidenceKey, EvidenceItem>>;
  operatorApproval?: { approvedBy: string; approvedAt: string } | null;
  evaluationDate?: string;
};

export type InstitutionalRouteResult = {
  decision: InstitutionalDecision;
  pathway: InstitutionalPathway | null;
  routeActive: boolean; // true only for VERIFIED_ROUTE
  reasons: string[];
  outstanding: { key: InstitutionalEvidenceKey | "operatorApproval"; requirement: string; problem: "missing" | "no_source" | "stale" | "rejected" }[];
  source: typeof INSTITUTIONAL_SOURCE;
  notice: string;
};

const NOTICE = "This describes a candidate authentication pathway under review. It is not legal advice, does not establish that any authority will act on the document, and never guarantees acceptance by the receiving authority.";
const today = () => new Date().toISOString().slice(0, 10);
const isIsoDate = (value: unknown): value is string => typeof value === "string" && /^\d{4}-\d{2}-\d{2}/.test(value) && !Number.isNaN(Date.parse(value));
const daysBetween = (from: string, to: string) => (Date.parse(to.slice(0, 10)) - Date.parse(from.slice(0, 10))) / 86_400_000;

export function isInstitutionalOrigin(value: unknown): boolean {
  return value === INSTITUTIONAL_DOCUMENT_ORIGIN;
}

export function evaluateInstitutionalRoute(input: InstitutionalRouteInput): InstitutionalRouteResult {
  const evaluationDate = input.evaluationDate ?? today();
  const pathway = input.pathway && input.pathway in INSTITUTIONAL_PATHWAYS ? input.pathway : null;
  const done = (decision: InstitutionalDecision, reasons: string[], outstanding: InstitutionalRouteResult["outstanding"] = []): InstitutionalRouteResult =>
    ({ decision, pathway, routeActive: decision === "VERIFIED_ROUTE", reasons, outstanding, source: INSTITUTIONAL_SOURCE, notice: NOTICE });

  if (!isInstitutionalOrigin(input.documentOrigin)) return done("UNKNOWN", ["The document is not classified as issued by a supranational or intergovernmental organisation."]);
  if (!isIsoDate(evaluationDate)) return done("UNKNOWN", ["The evaluation date is not a valid date."]);

  const unknown: string[] = [];
  if (!String(input.issuingOrganisation ?? "").trim()) unknown.push("The issuing organisation is not identified.");
  const host = resolvePlace(input.hostState);
  if (!host) unknown.push("The host State where the document was issued is not identified.");
  if (!String(input.documentCategory ?? "").trim()) unknown.push("The document category is not identified.");
  if (!input.documentForm) unknown.push("Whether the original or a certified copy is to be authenticated is not established.");
  if (!pathway) unknown.push("No candidate authentication pathway has been selected for review.");
  if (unknown.length || !host || !pathway) return done("UNKNOWN", unknown);

  // Every pathway ends in an apostille issued by the HOST State's Competent Authority.
  if (!isApostilleConventionInForce(host, evaluationDate)) {
    return done("UNSUPPORTED", ["The Apostille Convention is not in force for the host State on this date, so none of the HCCH candidate pathways can end in an apostille."]);
  }
  if (pathway === "DIRECT_COMPETENT_AUTHORITY" && input.documentForm === "certified_copy") {
    return done("UNSUPPORTED", ["Direct apostille by the Competent Authority applies to the organisation's own document; a copy needs the notarial or intermediary pathway."]);
  }

  const reasons: string[] = [];
  let conditional = false;
  if (!String(input.destination ?? "").trim()) {
    conditional = true;
    reasons.push("The destination is not identified, so the treaty relationship cannot be evaluated.");
  } else {
    // The document category goes in too, so a Party's declared document limitations keep the
    // pathway conditional instead of activating a route.
    const treaty = evaluateApostilleRelationship({ origin: host, destination: String(input.destination), evaluationDate, documentType: input.documentCategory });
    if (treaty.status === "APOSTILLE_NOT_APPLICABLE") return done("UNSUPPORTED", [`An apostille issued by the host State does not apply for this destination. ${treaty.reasons[0] ?? ""}`.trim()]);
    if (treaty.status !== "APOSTILLE_APPLICABLE") {
      conditional = true;
      reasons.push(`The treaty relationship between the host State and the destination is not settled. ${treaty.reasons[0] ?? ""}`.trim());
    }
  }

  const outstanding: InstitutionalRouteResult["outstanding"] = [];
  for (const key of INSTITUTIONAL_PATHWAY_EVIDENCE[pathway]) {
    const item = input.evidence?.[key];
    const requirement = INSTITUTIONAL_EVIDENCE[key];
    if (item?.state === "rejected") outstanding.push({ key, requirement, problem: "rejected" });
    else if (!item || item.state !== "verified") outstanding.push({ key, requirement, problem: "missing" });
    else if (!String(item.source ?? "").trim() || !isIsoDate(item.verifiedAt)) outstanding.push({ key, requirement, problem: "no_source" });
    else if (item.verifiedAt.slice(0, 10) > evaluationDate || daysBetween(item.verifiedAt, evaluationDate) > INSTITUTIONAL_EVIDENCE_MAX_AGE_DAYS) outstanding.push({ key, requirement, problem: "stale" });
  }
  if (outstanding.some((o) => o.problem === "rejected")) {
    return done("UNSUPPORTED", ["An authority or official source has declined a requirement of this pathway; another pathway must be reviewed.", ...reasons], outstanding);
  }

  const approval = input.operatorApproval;
  const approved = Boolean(approval && String(approval.approvedBy ?? "").trim() && isIsoDate(approval.approvedAt) && approval.approvedAt.slice(0, 10) <= evaluationDate);
  if (!approved) outstanding.push({ key: "operatorApproval", requirement: "An authorized operator has approved this pathway for this document.", problem: "missing" });
  // Approval given before the evidence was (re)verified does not cover it. Full instants are
  // compared: a date-only value counts as the start of that day, so a same-day approval must
  // carry a time later than the evidence to cover it.
  if (approved && INSTITUTIONAL_PATHWAY_EVIDENCE[pathway].some((key) => { const at = input.evidence?.[key]?.verifiedAt; return isIsoDate(at) && Date.parse(at) > Date.parse(approval!.approvedAt); })) {
    outstanding.push({ key: "operatorApproval", requirement: "Operator approval must follow the latest evidence verification.", problem: "stale" });
  }

  if (outstanding.length || conditional) {
    return done("CONDITIONAL_REVIEW", [`${INSTITUTIONAL_PATHWAYS[pathway]} This is a candidate pathway: ${outstanding.length} requirement(s) remain to be evidenced or approved.`, ...reasons], outstanding);
  }
  return done("VERIFIED_ROUTE", [`${INSTITUTIONAL_PATHWAYS[pathway]} Every requirement is evidenced from an identified source and approved by an operator.`]);
}
